                };

                if(captionEl.children.length >= 1) {                    
                    item.title = captionEl.innerHTML;
                }

                if(linkEl.children.length > 0) {
                    item.msrc = linkEl.children[0].children[0].getAttribute('src');
                }

                item.el = figureEl;
                items.push(item);
