var newFileUpload = function() {
    // Object variables
    var fileUploadWrapper;
    var fileUploadMessageObj;
    var fileUploadMessageOriginal = "No file selected.";
    var fileInput;
    var fileUploadIcon;
    var inputLabel;

    // Checks if the value is valid
    var isValid = function(value) {
        if(/^\s*$/.test(value)) {
            return false;
        }
        return true;
    };

    // Sanitizes a string to help mitigating XSS attacks
    var sanitize = function sanitize(value) {
        if (typeof value === 'string') {
            if (value !== undefined && value !== null && value !== '') {
                return value.replace(/</g, '‹').replace(/>/g, '›');
            }
        }
        return value;
    }

    // Handler when the input chages
    var onFileInputChange = function() {
        var newFile;
        var fileUploadDelete = fileUploadWrapper.querySelector('.file-upload-delete');

        // Sanitize the input name in order to avoid XSS attacks
        var fileNameAux = sanitize(fileInput.value);

        if(isValid(fileNameAux)) {

            // Adds active class
            if(fileUploadWrapper && !fileUploadWrapper.classList.contains('active')) {
                fileUploadWrapper.classList.add('active');
            }

            // Creates a new div with the name of the file
            newFile = document.createElement('div');
            newFile.innerHTML = fileNameAux.replace("C:\\fakepath\\", "");

            // Creates a new icon to delete function
            fileUploadDelete.setAttribute('tabindex', '0');
            fileUploadDelete.addEventListener('click', onDeleteIconClick);
            fileUploadDelete.addEventListener('keypress', onDeleteIconOnKeypress);

            // Appends the file name to the message placeholder
            fileUploadMessageObj.innerHTML = "";
            fileUploadMessageObj.appendChild(newFile);
            fileUploadDelete.setAttribute('aria-label', 'Delete file ' + fileInput.files[0].name);
            fileUploadIcon.setAttribute('aria-label', 'Uploaded ' + fileInput.files[0].name + ' file');

        } else {
            fileUploadDelete.setAttribute('tabindex', '-1');

            // Removes active class
            if(fileUploadWrapper && fileUploadWrapper.classList.contains('active')) {
                fileUploadWrapper.classList.remove('active');
            }

            // Replaces the name of the archive to the empty message
            fileUploadMessageObj.innerHTML = fileUploadMessageOriginal;
            fileUploadIcon.setAttribute('aria-label', 'Upload File');
        }

        // Focus on the uploadIcon after selecting or deleting a file
        fileUploadIcon.focus();
    };

    // Handler for delete icon events
    var handleDeleteIconEvent = function(evt){
        // Resets input's value
        fileInput.value = "";

        // Removes on delete button event listeners
        if(evt.target && evt.target.classList.contains('file-upload-delete')) {
            evt.target.removeEventListener('click', onDeleteIconClick);
            evt.target.removeEventListener('keypress', onDeleteIconOnKeypress);
        }

        // Resets the UI
        onFileInputChange();
    }

    // Handler for delete icon keypress
    var onDeleteIconOnKeypress = function(evt) {
        if(evt.keyCode == "13" || evt.keyCode == "32") {
            handleDeleteIconEvent(evt);
        }
    };

    // Handler for delete icon click
    var onDeleteIconClick = function(evt) {
        handleDeleteIconEvent(evt);
    };

    var handleUploadIconEvent = function(){
        inputLabel.click();
    }

    var onUploadIcOnClick = function(){
        handleUploadIconEvent();
    }

    var onUploadIcOnKeypress = function(evt){
        if(evt.keyCode == "13" || evt.keyCode == "32") {
            handleUploadIconEvent();
        } 
    }

    // Start the upload
    var start = function(widgetId) {
        if(widgetId) {
            // Gets file input
            fileUploadWrapper = document.querySelector('#' + widgetId + ' .file-upload');
            if(fileUploadWrapper) {
                fileUploadMessageObj = fileUploadWrapper.querySelector('.file-upload-message');
                fileInput = fileUploadWrapper.querySelector('input[type=file]');
                fileUploadIcon = fileUploadWrapper.querySelector('.file-upload-icon');

                // Saves the original message if it exists
                if(fileUploadMessageObj.innerHTML.length > 0) {
                    fileUploadMessageOriginal = fileUploadMessageObj.innerHTML;
                }

                // Adds event listeners if file input exists
                if(fileInput) {
                    var fileInputId = fileInput.id;
                    inputLabel = document.createElement('label');
                    inputLabel.setAttribute('for', fileInputId);
                    fileUploadWrapper.appendChild(inputLabel);

                    // Add Accessibility attributes
                    fileUploadIcon.setAttribute('aria-controls', fileInputId);
                    fileInput.setAttribute('tabindex', '-1');
                    fileInput.setAttribute('aria-hidden', true);
                    fileInput.setAttribute('aria-labelledby', fileUploadIcon.id);

                    // Add events
                    fileUploadIcon.addEventListener('keypress', onUploadIcOnKeypress);
                    fileUploadIcon.addEventListener('click', onUploadIcOnClick);

                    fileInput.addEventListener('change', onFileInputChange);
                }
            }
        }
    };

    return {
        init: function(widgetId) {
            start(widgetId);
            osAjaxBackend.BindAfterAjaxRequest(function() {
                start(widgetId);
            })
        }
    };
}

var newDropdownSelect = function() {

    // Objects
    var elementId;
    var elementClass;
    var extendedOptions;
    var choices;
    var options;

    var start = function(widgetId, classParam, optionsParam, advancedFormat) {
        elementId = document.getElementById(widgetId);

        if(classParam.length > 0) {
            elementClass = classParam;
        }

        extendedOptions = advancedFormat;
        options = {
            noResultsText: optionsParam.noResultsText,
            searchResultLimit: optionsParam.searchResultLimit,
            searchEnabled: optionsParam.searchEnabled,
            shouldSort: false,
            callbackOnInit: onInit,
        };

        if(extendedOptions.length > 0) {
            var advancedObj = eval('(' + extendedOptions + ')');
            options = mergeJSON(options, advancedObj);
        }

        if(elementId) {
            choices = new Choices('#' + widgetId, options);
        };

        // AdvancedFormat function
        function mergeJSON(target, add) {
            function isObject(obj) {
                if (typeof obj == 'object') {
                    for (var key in obj) {
                        if (obj.hasOwnProperty(key)) {
                            return true; // search for first object prop
                        }
                    }
                }
                return false;
            }
            for (var key in add) {
                if (add.hasOwnProperty(key)) {
                    if (target[key] && isObject(target[key]) && isObject(add[key])) {
                        mergeJSON(target[key], add[key]);
                    } else {
                        target[key] = add[key];
                    }
                }
            }
            return target;
        };

        // Recursive Function for closest() in IE
        var closestFn = function(element, classToSearch) {
            if(element && element.classList.contains(classToSearch)) {
                return element;
            } else if(!element || element && element.classList.contains('layout')) {
                return false;
            } else {
                return closestFn(element.parentElement, classToSearch);
            }
        };

        function isEmpty(str) {
            return (!str || 0 === str.length);
        }

       // Function to create div around search input (necessary for css search icon)
       var createEl = function(query, tag, className, innerHTML) {
           var queryList = document.querySelectorAll(query);

           for(var i = 0; i < queryList.length; i++) {
                var elem = queryList[i];
                var wrapper = document.createElement(tag);
                if(!isEmpty(innerHTML)) { 
                    wrapper.innerHTML = innerHTML 
                }

                if(!closestFn(elem, className)){
                    elem.parentElement.insertBefore(wrapper, elem);
                    wrapper.appendChild(elem);
                    wrapper.classList.add(className);

                }
           }
        };

        // Creates div around search input
        createEl('.choices__input--cloned', 'div', 'search--wrapper', '');

        // Add title do input
        if(choices) {
            choices.input.setAttribute('title', "Search");
        }

        // Get all elements with class .choices
        var choicesClass = document.querySelectorAll('.choices');
        var choicesListClass = document.querySelectorAll('.choices__list');

        // Check for rtl and set correct attribute on every element
        if(document.body.classList.contains('is-rtl')) {
            for(var i = 0; i < choicesClass.length; i++) {
                choicesClass[i].setAttribute('dir', 'rtl');
            }
            for(var i = 0; i < choicesListClass.length; i++) {
                choicesListClass[i].setAttribute('dir', 'rtl');
            }
        };

        // Verify if select has the attribute disabled        
        var choicesSelect = document.querySelectorAll('.choices');

        if(choicesSelect) {
            for(var i = 0; i < choicesSelect.length; i++) {
                var choicesDisabled = choicesSelect[i].querySelector('select');

                if(choicesDisabled.hasAttribute('disabled')) {
                    choicesSelect[i].classList.add('choices-disabled');
                };       
            };
        };

        /*
         * Fix issue with DropdownSelect not displaying correctly and the options not being selectable when inside EditableTable.
         *
         * The issues only occur when the dropdown is opened, so we use the showDropdown and the hideDropdown events to add and remove the classes that fix the issues.
         */
        var isFirefox = document.body.classList.contains('firefox');
        var editableTables = document.querySelectorAll(".EditableTable")
        var isInsideEditableTable = false;

        for (var i = 0; i < editableTables.length; i++){
            if(editableTables[i].contains(choices.passedElement)) isInsideEditableTable = true;
        }

        // Add the event listeners if in Firefox and the dropdown is inside a EditableTable
        if(isFirefox && isInsideEditableTable){
            choices.passedElement.addEventListener(
              'showDropdown',
              function(event) {
                editableTable = event.currentTarget.closest(".EditableTable.OnEdit"); // get the EditableTable element
                editableTable.classList.add("transform-none"); // add the class to the EditableTable element
                rowControlGroup = document.querySelector(".RowControlGroup"); // get the RowControlGroup element
                rowControlGroup.classList.add("visibility-hidden"); // add the class to the RowControlGroup element
              },
              false,
            );

            choices.passedElement.addEventListener(
              'hideDropdown',
              function(event) {
                editableTable = event.currentTarget.closest(".EditableTable.OnEdit"); // get the EditableTable element
                editableTable.classList.remove("transform-none");// remove the class to the EditableTable element
                rowControlGroup = document.querySelector(".RowControlGroup"); // get the RowControlGroup element
                rowControlGroup.classList.remove("visibility-hidden"); // remove the class to the RowControlGroup element
              },
              false,
            );
        }

    };

    var onInit = function() {

        // Get select input
        var selectElement = document.querySelector(this.element);
        var choicesElement = this.containerOuter;

