var ButtonLoading = function() {

    // Objects
    var elemId;
    var IsLoading;
    var button;

    var start = function(widgetId, isLoading) {

        elemId = document.getElementById(widgetId);
        button = elemId.querySelector('.btn');
        IsLoading = (isLoading === 'True');

        button.addEventListener('keydown', onButtonKeypress);

    };

    var onButtonKeypress = function(e){

        if((e.keyCode == "13" || e.keyCode == "32") && IsLoading) {
          e.preventDefault();
        } else {
            button.removeEventListener('keydown', onButtonKeypress); 
            return true;
        }

    };

    return {
        init: function(widgetId, isLoading) {
            start(widgetId, isLoading);
        }
    };
};

var textCounter = function() { 
    var widget;
    var numberBox;
    var maxValue;
    var isDesc;
    var currValue;
    var enteredText;
    var lineBreaks;
    var characterCount;

    var start = function(widgetIdParam, containerId, limit, isDescending) {
        widget = document.getElementById(widgetIdParam);
        numberBox = document.getElementById(containerId);
        maxValue = limit;
        isDesc = (isDescending === "True");
        currValue = isDesc ? maxValue : 0;

        if(widget) {
            widget.addEventListener('keyup', setValue);

            // set number value for the first time, removing the 500 placeholder that we have there
            setValue();
        }
    }   

    function setValue() {
        enteredText = widget.value;
        lineBreaks = (enteredText.match(/\n/g)||[]).length;

        // count of linbreaks and characters
        characterCount = enteredText.length + lineBreaks;

        if(isDesc) {
            currValue = maxValue - characterCount;
            numberBox.innerText = currValue; 
        } else {
            // this verification is done as a safeguard in case if the user forgets to set the max length on the input
            if(characterCount <= maxValue) {
                numberBox.innerText = characterCount; 
            }
        }
    }

    return {
        init: function(widgetIdParam, containerId, limit, isDescending) {
            start(widgetIdParam, containerId, limit, isDescending);
        }
    }
}

var flipContent = function() {
    // Objects
    var flipContentWidget;
    var flipContentWrapper;
    var flipContentFront;
    var flipContentBack;
    var onFlippedEvent;
    var elementsOnFlipContent;

    var start = function(widgetIdParam, onFlippedEventParam, triggerEventParam) {
        // Sets main objects
        flipContentWidget = document.getElementById(widgetIdParam);
        flipContentWrapper = flipContentWidget.querySelector('.flip-content');
        flipContentFront = flipContentWidget.querySelector('.flip-content-front');
        flipContentBack = flipContentWidget.querySelector('.flip-content-back');
        onFlippedEvent = onFlippedEventParam;

        // Add eventListener if the selected trigger is Click
        if(triggerEventParam === 'click'){
            flipContentWrapper.addEventListener('click', onFlipContentClick);
            flipContentWrapper.addEventListener('keydown', onFlipContentKeypress);
            flipContentWrapper.setAttribute('role','button');
            flipContentWrapper.setAttribute('tabindex','0');
        }

        // Prevent events if the selected trigger is Hover
        if(!flipContentWrapper.classList.contains('is--hover')){
            flipContentFront.addEventListener('transitionend', onFlipContentTransitionFront);
        }

    };

    // Action to add or remove classes on flipContent
    var onFlipContentClick = function(e) {
        elementsOnFlipContent = ['input', 'select', 'button', 'textarea', 'a'];

        // Verify if exists inputs, textareas, select, links or buttons inside flipContent.
        //If exists, the click must be disabled
        if (elementsOnFlipContent.indexOf(e.target.tagName.toLowerCase()) !== -1) {
           return false;
        } else {
            if(flipContentWrapper.classList.contains('is--flipped')) {
                flipContentWrapper.classList.remove('is--flipped');
                changeAriaStates();
            } else {
                flipContentWrapper.classList.add('is--flipped');
                changeAriaStates();
            }
        }
    };

    // Action to change aria states
    var changeAriaStates = function() {
        if(flipContentWrapper.classList.contains('is--flipped')) {
            flipContentBack.setAttribute('aria-hidden','false');
            flipContentFront.setAttribute('aria-hidden','true');

        } else {
            flipContentBack.setAttribute('aria-hidden','true');
            flipContentFront.setAttribute('aria-hidden','false');
        }
    };

    // Function to add and remove transition eventListeners to prevents flipped events
    var onFlipContentTransitionFront = function() {
        flipContentFront.removeEventListener('transitionend', onFlipContentTransitionFront);
        flipContentBack.addEventListener('transitionend', onFlipContentTransitionBack);
        changeAriaStates();
        onFlipContentEvent();
    };

    // Function to add and remove transition eventListeners to prevents flipped events
    var onFlipContentTransitionBack = function() {
        flipContentFront.addEventListener('transitionend', onFlipContentTransitionFront);
        flipContentBack.removeEventListener('transitionend', onFlipContentTransitionBack);
        changeAriaStates();
        onFlipContentEvent();
    };

    // Action handdle the event when is flipped
    var onFlipContentEvent = function() {
        if(flipContentWrapper.classList.contains('is--flipped')) {
            TriggerEvents(onFlippedEvent, true); 
        } else {
            TriggerEvents(onFlippedEvent, false); 
        }
    };

    //Set keyboard interaction
    var onFlipContentKeypress = function(e) {
        if(e.keyCode == "32" || e.keyCode == "13") {
            onFlipContentClick();
            e.preventDefault();
            e.stopPropagation();
        } else if(e.keyCode == "27") {
            flipContentWrapper.classList.remove('is--flipped');
            changeAriaStates();
        }
    };

    return {
        init: function(widgetIdParam, onFlippedEventParam, triggerEventParam) {
            start(widgetIdParam, onFlippedEventParam, triggerEventParam);
        }
    }
};

var newTabs = function () {
    // Variables
    var tabs;
    var tabsHeader;
    var tabsHeaderItems;
    var tabsContentItems;
    var tabsContent;
    var activeTabHeader;
    var activeTabContent;
    var activeTab;
    var activeTabAsIndex;
    var widgetId;
    var changeId;
    var currentTabIndex;
    var inputsOnTabs;

    var start = function (widgetIdParam, onChangeId) {
        // Sets main objects
        widgetId = widgetIdParam;
        tabs = document.querySelector('#' + widgetId + ' > .tabs');

        // Ensure that tabs instance exists in the DOM
        if(!tabs) {
            return;
        }

        tabsHeader = tabs.querySelector('.tabs-header');
        tabsContent = tabs.querySelector('.tabs-content');

        tabsHeaderItems = Array.prototype.filter.call(tabsHeader.querySelectorAll('.tabs-header-item'), function (el) {
            return el.closest('.tabs') === tabs;
        });

        // Accessibility tabindex change values to all tabsHeaderItems
        tabsHeaderItemsParentTabId = '';
        tabsHeaderItemsCount = 0;
        tabsHeaderItems.forEach(function (item) {
            item.setAttribute('tabindex', "-1");
            // Check if the parent has changed
            if (tabsHeaderItemsParentTabId != item.parentElement.id) {
                tabsHeaderItemsParentTabId = item.parentElement.id;
                tabsHeaderItemsCount = 0;
                item.setAttribute('tabindex', "0");
            }
            item.setAttribute('data-tabheader-index', tabsHeaderItemsCount++);

            // Adds the necessary event listener to tabs
            // Adding event listeners to the wrapper (tabs) instead of each children (tabHeaderItem) to avoid unnecessary multiple event listeners
            item.addEventListener('click', onTabsClick);
            item.addEventListener('keydown', onTabsKeypress);
        });

        tabsContentItems = Array.prototype.filter.call(tabsContent.querySelectorAll('.tabs-content-item'), function (el) {
            return el.closest('.tabs') === tabs;
        });

        // Accessibility tabindex change values to all tabsContentItems
        var tabsContentTotal_I = 0;
        tabsContentItems.forEach(function (item) {
            item.setAttribute('tabindex', "-1");

            // define the aria-labelledby attribute
            if (tabsHeaderItems[tabsContentTotal_I])
                item.setAttribute('aria-labelledby', tabsHeaderItems[tabsContentTotal_I].getAttribute('id'));
            tabsContentTotal_I++;
        });

        changeId = onChangeId;
        inputsOnTabs = ['input', 'select', 'button', 'textarea'];
        var _auxActiveTabHeaderItem, _auxActiveTabContentItem;
        if(tabs.dataset.activeTabAsIndex === 'True'){activeTabAsIndex = true} else {activeTabAsIndex = false};

        if(activeTabAsIndex){
            // Replace every character that's not a digit with '' and use the digits as the activeTab
            activeTab = parseInt(tabs.dataset.activeTab.replace(/\D/g, ''));
        } else {
            activeTab = tabs.getAttribute('data-active-tab');
            if(activeTab !== "tab-"){
                _auxActiveTabHeaderItem = tabs.querySelector('.tabs-header-item[data-tab = '+activeTab+']');
                _auxActiveTabContentItem = tabs.querySelector('.tabs-content-item[data-tab = '+activeTab+']');
            }

        }

        if(activeTabAsIndex && activeTab > 0 && tabsHeaderItems[activeTab] && tabsContentItems[activeTab]) {
            // Use activeTab as index to locate the right tab header and tab content 
            activeTabHeader = tabsHeaderItems[activeTab];
            activeTabContent = tabsContentItems[activeTab];
        } else if(activeTab.length > 0 && _auxActiveTabHeaderItem && _auxActiveTabContentItem) {
            // In case activeTabAsIndex is false let's check if we have already an active header and content identied
            activeTabHeader = _auxActiveTabHeaderItem;
            activeTabContent = _auxActiveTabContentItem;
        } else {
            // Select the first as active if empty or doesn't match
            activeTabHeader = tabsHeaderItems[0];
            activeTabContent = tabsContentItems[0];
            activeTab = 0;
        }   

        // Sets header and content as active
        setTabAsActive(activeTabHeader, activeTabContent);
    };

    var setTabAsActive = function (header, content) {
        // Adds active class to active tab header and tab content
        if (header && !header.classList.contains('active')) {
            header.classList.add('active');
            header.setAttribute('aria-selected', 'true');

            // Accessibility tabindex change values
            header.setAttribute('tabindex', "0");
        }
        if (content && !content.classList.contains('active')) {
            content.classList.add('active');
            content.setAttribute('aria-hidden', 'false');

            // Accessibility tabindex change values
            content.setAttribute('tabindex', "0");
        }
    };

    var onTabsKeypress = function (e) {
        var nextTabItem = document.activeElement; // set active as default
        var items = tabsHeaderItems.length;

        // Verify if exists inputs, textareas, select or buttons inside tabs when using arrow key to navigate.
        if (document.activeElement && inputsOnTabs.indexOf(document.activeElement.tagName.toLowerCase()) !== -1) {
            return false;
        } else {
            if (tabs.classList.contains('tabs-horizontal')) {
                // Arrow Right
                if (e.keyCode == "39") {
                    nextTabItem = document.activeElement.nextElementSibling;
                    if (!nextTabItem) {
                        nextTabItem = tabsHeaderItems[0];
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    else {
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                }
                // Arrow Left
                if (e.keyCode == "37") {
                    nextTabItem = document.activeElement.previousElementSibling;
                    if (!nextTabItem) {
                        nextTabItem = tabsHeaderItems[items - 1];
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    else {
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                }
            }

            if (tabs.classList.contains('tabs-vertical')) {
                // Arrow Down - Act as Right
                if (e.keyCode == "40") {
                    nextTabItem = document.activeElement.nextElementSibling;
                    if (!nextTabItem) {
                        nextTabItem = tabsHeaderItems[0];
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    else {
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    e.preventDefault();
                }
                // Arrow Up - Act as Left
                if (e.keyCode == "38") {
                    nextTabItem = document.activeElement.previousElementSibling;
                    if (!nextTabItem) {
                        nextTabItem = tabsHeaderItems[items - 1];
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    else {
                        nextTabItem.focus();
                        nextTabItem.click();
                    }
                    e.preventDefault();
                }
            }
        }
        // If pressing Space key
        if (e.keyCode == "32") {
            nextTabItem.click();

            // Verify if exists inputs, textareas, select or buttons inside tabs.
            // If exists, the preventDefault must be disabled to accept spaces inside the widgets
            if (document.activeElement && inputsOnTabs.indexOf(document.activeElement.tagName.toLowerCase()) !== -1) {
                return false;
            } else {
                e.preventDefault();
            }
        }

    };

    var onTabsClick = function (e) {
        var target = e.target.closest('.tabs-header-item');

        // Checks if is tabsHeader and if the clicked tab isn't the active tab already
        if (target && !target.classList.contains('active')) {

            var clickedTabDataInfo = target.getAttribute('data-tab');

            var newActiveTabContent = Array.prototype.filter.call(tabsContent.querySelectorAll(".tabs-content-item[data-tab = '" + clickedTabDataInfo + "']"), function (el) {
                return el.closest('.tabs') === tabs;
            });

            // Removes the active class
            if (activeTabHeader && activeTabHeader.classList.contains('active')) {
                activeTabHeader.classList.remove('active');
                activeTabHeader.setAttribute('aria-selected', 'false');

                // Accessibility tabindex change values
                activeTabHeader.setAttribute('tabindex', "-1");
            }
            if (activeTabContent && activeTabContent.classList.contains('active')) {
                activeTabContent.classList.remove('active');
                activeTabContent.setAttribute('aria-hidden', 'true');

                // Accessibility tabindex change values
                activeTabContent.setAttribute('tabindex', "-1");
            }

            // Sets header and content as active
            setTabAsActive(target, newActiveTabContent[0]);

            // Update active objects
            activeTabHeader = target;
            activeTabContent = newActiveTabContent[0];
            activeTab = clickedTabDataInfo;

            // Updates data-active-tab attribute
            tabs.setAttribute('data-active-tab', activeTab);

            // To TriggerEvents after the previous actions
            setTimeout(function () {
                TriggerEvents(changeId, currentTabIndex);
            }, 0);

            // get index from the active Tab
            getCurrentIndex(target);

        }

    };

    var getCurrentIndex = function (ItemHeader) {
        currentTabIndex = parseInt(ItemHeader.dataset.tabheaderIndex);
    }

    return {
        init: function (widgetIdParam, onChangeId) {
            start(widgetIdParam, onChangeId);
            // Redraw pattern after a list is refreshed with ajax refresh
            osAjaxBackend.BindAfterAjaxRequest(function () {
                if (this[0].requestEvent.screenActionName !== 'Tabs.OnChange') {
                    start(widgetIdParam, onChangeId);
                }
            });
        }
    }
};

var NavigationBar = function() { 
