var Gallery = function() {  
    var widgetElementId;
    var nritemsDesktop;
    var nritemsTablet;
    var nrItemsPhone;

    var galleryEl;
    var listEl;
    var galleryItems;
    var columnWidth;
    var divider;
    var gutter;
    var margin;
    var rtime;
    var timeout = false;
    var delta = 200;

    function initGallery(widgetId, itemsDesktop, itemsTablet, itemsPhone) {        

        // get device define column width
        var body = document.querySelector("body");
        isDesktop = body.classList.contains("desktop");
        isTablet = body.classList.contains("tablet");
        isPhone = body.classList.contains("phone");

        widgetElementId = widgetId;
        nritemsDesktop = itemsDesktop;
        nritemsTablet = itemsTablet;
        nrItemsPhone = itemsPhone;

        if(isDesktop) {
            divider = itemsDesktop;
        } else if(isTablet) {
            divider = itemsTablet;
        } else if(isPhone) {
            divider = itemsPhone;
        }

        //gutter = GutterSize;
        gutter = 20;

        // 1.96078431372549 gutter measure in Platform Grid
        margin = 1.96;
        columnWidth = (100 - (gutter ? (divider -1) * margin : 0)) / divider;

        // define the gallery element
        galleryEl = document.getElementById(widgetId);

        // define list element
        if(galleryEl.children[0].classList.contains("ListRecords")) {
            listEl = galleryEl.children[0];
            galleryItems = listEl;
        } else {
            galleryItems = galleryEl;
        }

        galleryItems.classList.add("gallery-content");
        galleryItems.classList.add("is--hidden");

        // resize gallery items
        resizeElements(galleryItems);

        galleryItems.classList.remove("is--hidden");
        galleryItems.classList.add("is--visible");
    }

    var resizeElements = function(el) {
        el.classList.remove("is--visible");
        el.classList.add("is--hidden");

        var isRTL = document.querySelector(".is-rtl");

        for(var i=0; i < el.children.length; i++) {
            var element = el.children[i];

            element.classList.add("gallery-item");

            // remove margins
            if(isRTL) {
                element.style.removeProperty('margin-right');
            } else {
                element.style.removeProperty('margin-left');
            }
            element.style.removeProperty('margin-left');
            element.style.removeProperty('margin-top');

            // set width to all elements
            element.style.width = columnWidth + "%";

            // set left margin to all except first in row
            if(i%divider !== 0 && gutter) {
                if(isRTL) {
                    element.style.marginRight = margin + "%";   
                } else {
                    element.style.marginLeft = margin + "%";   
                }
            }

            // set margin top to all expect first row
            if(i >= divider && gutter) {
                element.style.marginTop = margin + "%";    
            }

        }        
    }

    function resizeend() {
        if (new Date() - rtime < delta) {
            setTimeout(resizeend, delta);
        } else {
            timeout = false;                
            initGallery(widgetElementId, nritemsDesktop, nritemsTablet, nrItemsPhone);
        } 
    }

    window.addEventListener("resize", function() {                
        rtime = new Date();
        if (timeout === false) {
            timeout = true;
            setTimeout(resizeend, delta);
        }        
    }, false);

    return {
        init: function(widgetId, ItemsDesktop, ItemsTablet, ItemsPhone) {
            initGallery(widgetId, ItemsDesktop, ItemsTablet, ItemsPhone);
        }
    }
};

var trapFocusPopup = function() {
    var element = document;

     var start = function() {
        var popElem = document.querySelector('.os-internal-ui-dialog');
        var focusableClose = window.parent.document.querySelector('a.os-internal-ui-dialog-titlebar-close, a.os-internal-ui-dialog-titlebar-close-no-title');
        var focusableEls = element.querySelectorAll('a[href]:not([disabled]), button:not([disabled]), textarea:not([disabled]), input[type="text"]:not([disabled]), input[type="radio"]:not([disabled]), input[type="checkbox"]:not([disabled]),input[type="submit"]:not([disabled]), select:not([disabled])');
        firstFocusableEl = focusableEls[0];  
        lastFocusableEl = focusableEls[focusableEls.length - 1];
        KEYCODE_TAB = 9;
        KEYCODE_ESCAPE = 27;

        if(focusableClose) {
            focusableClose.setAttribute('tabindex', "0");
        }

        document.addEventListener('keydown', function(e) {
            var isTabPressed = (e.key === 'Tab' || e.keyCode === KEYCODE_TAB);
            var isEscapedPressed = (e.key === 'Escape' || e.keyCode === KEYCODE_ESCAPE);

            if(!isTabPressed && !isEscapedPressed) {
                return;
            }

            if (isEscapedPressed && focusableClose) /* Escape */ {
                focusableClose.click();
                e.preventDefault();
            } 

            if ( e.shiftKey ) /* shift + tab */ {
                if (document.activeElement === firstFocusableEl && focusableClose) {
                    focusableClose.focus();
                    e.preventDefault();
                }
            } else if (document.activeElement === lastFocusableEl && focusableClose) {
                focusableClose.focus();
                e.preventDefault();
            } 
        });

        firstFocusableEl.focus();

    }

    return {
        init: function() {
            start();
        }
    }
}

document.addEventListener("DOMContentLoaded", function(event) {

    // detect IE11 and IE10
    var isIE = document.body.classList.contains("ie11") || document.body.classList.contains("ie10");

    // get total header size to space the main content
    var headerGutter = document.querySelector(".header").offsetHeight;

    if(!isIE) {
        var headerContent = document.querySelector(".header-content");        

        if(headerContent) {
            var headerContentSize = headerContent.offsetHeight;

            if(headerContentSize > 0) {            
                document.querySelector(".main").style.setProperty('--header-gutter', headerGutter + "px");
            }
        }    
    }

    // get the MenuIcon and Menu DOM elements    
    var menuIcon = document.querySelector(".menu-icon");
    var menu = document.querySelector(".Application_Menu");
    var navigation = document.querySelector(".navigation");

    if(menu) {
        menu.classList.remove("animate");
   }

    // add the event listeners if both elements exist
    if(navigation !== null && menuIcon !== null) {
        // open the menu
        menuIcon.addEventListener("click", function() {
            navigation.classList.add("is--visible");
            navigation.classList.remove("is--hidden");
        });

        // close the menu
        navigation.addEventListener('click', function(e) {
            // close the menu if the click is on the overlay
            if(e.target === navigation) {
                navigation.classList.remove('is--visible');
                navigation.classList.add('is--hidden');
            }
        });
    }
});

